package lockfile

import (
	"path/filepath"
	"testing"
)

// corpusRepo reads one fixture repository under testdata/corpus.
func corpusRepo(t *testing.T, owner, repo string) Lock {
	t.Helper()
	lock, err := Read(filepath.Join(repoRoot(t), "testdata", "corpus", owner, repo))
	if err != nil {
		t.Fatalf("reading %s/%s: %v", owner, repo, err)
	}
	return lock
}

// The corpus has to contain a repository whose every reference the lockfile accounts for, or
// nothing exercises the covered path. Generated by the pinned CLI with `--no-narrow`, so the
// workflow refs are the ones a reader wrote rather than ones the tool rewrote.
func TestTheCorpusHasAFullyCoveredRepository(t *testing.T) {
	lock := corpusRepo(t, "lockedcorp", "pinned-service")
	if lock.Coverage != Covered {
		t.Fatalf("coverage = %q, want %q", lock.Coverage, Covered)
	}
	for _, workflow := range []string{".github/workflows/ci.yml", ".github/workflows/release.yml"} {
		if got := lock.Workflow(workflow); got != Covered {
			t.Errorf("%s = %q, want %q", workflow, got, Covered)
		}
	}
	if _, ok := lock.Selected(".github/workflows/ci.yml", "actions/checkout@v4"); !ok {
		t.Error("no selection for a reference the lockfile covers")
	}
}

// Coverage is per workflow, and a repository can hold both states at once. `gh actions-lock`
// v0.1.6 skips any workflow containing a local `./` action -- "local path actions are not yet
// supported" -- so the uncovered half of this fixture is what the tool itself produces.
func TestTheCorpusHasARepositoryCoveredOnlyInPart(t *testing.T) {
	lock := corpusRepo(t, "lockedcorp", "partial-adoption")
	if lock.Coverage != Covered {
		t.Fatalf("repository coverage = %q, want %q", lock.Coverage, Covered)
	}
	if got := lock.Workflow(".github/workflows/build.yml"); got != Covered {
		t.Errorf("build.yml = %q, want %q", got, Covered)
	}
	// Present in the repository, absent from the lockfile: not the same fact as having no lock.
	if got := lock.Workflow(".github/workflows/local-only.yml"); got != NotOnboarded {
		t.Errorf("local-only.yml = %q, want %q", got, NotOnboarded)
	}
}

// The fixture selection work needs: a lockfile that covers a reference and selects a *different*
// commit than resolving the tag would. No tool can produce a stale lock on demand, so this one is
// assembled -- but from real values. `actions/checkout@v4` pointed at v4.2.2's commit
// (11bd7190) before it moved to v4.4.0's (11d5960), and this records the former.
//
// This is the only lockfile in the corpus that the pinned CLI did not generate. If it ever agrees
// with live resolution, the fixture has stopped testing anything and must be re-staled.
func TestTheCorpusHasALockThatSelectsAnOlderCommitThanItsTag(t *testing.T) {
	const (
		staleCommit = "11bd71901bbe5b1630ceea73d27597364c9af683" // actions/checkout v4.2.2
		liveCommit  = "11d5960a326750d5838078e36cf38b85af677262" // what v4 resolves to now
	)
	lock := corpusRepo(t, "lockedcorp", "stale-selection")
	if lock.Coverage != Covered {
		t.Fatalf("coverage = %q, want %q", lock.Coverage, Covered)
	}
	got, ok := lock.Selected(".github/workflows/ci.yml", "actions/checkout@v4")
	if !ok {
		t.Fatal("no selection; the fixture exists to have one")
	}
	if got != staleCommit {
		t.Errorf("selected %s, want the stale commit %s", got, staleCommit)
	}
	if got == liveCommit {
		t.Error("the fixture now selects what the tag resolves to, so it tests nothing")
	}
}
